<div class="form-section"><span class="eyebrow">DETALLES DEL PRODUCTO</span><h2><?= $isEdit?'Editar producto':'Registrar producto' ?></h2>
<label>Catálogo <span>*</span><select name="catalog_id" required><?php foreach($catalogOptions as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)form_value($formData, 'catalog_id', $product['catalog_id']??$selectedCatalog)===(int)$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select></label>
<label>Nombre del producto <span>*</span><input name="name" required maxlength="140" value="<?= h(form_value($formData, 'name', $product['name']??'')) ?>" placeholder="Ej. Audífonos inalámbricos"></label>
<label>Categoría<select name="category_id"><option value="">Sin categoría</option><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (int)form_value($formData, 'category_id', $product['category_id']??0)===(int)$cat['id']?'selected':'' ?>><?= h($cat['name']) ?></option><?php endforeach; ?></select></label>
<label>Descripción<textarea name="description" rows="4" placeholder="Características principales..."><?= h(form_value($formData, 'description', $product['description']??'')) ?></textarea></label>
<label>Precio (COP) <span>*</span><input type="number" name="price" min="0" step="100" required value="<?= h(form_value($formData, 'price', $product['price']??'0')) ?>"></label>
